// The canonical quiet NaN, the one NaN the protocol allows (deltaTSec).
inline double CanonicalNaN() {
  uint64_t u = 0x7FF8000000000000ull;
  double d;
  memcpy(&d, &u, 8);
  return d;
}
inline bool IsCanonicalNaN(double d) {
  uint64_t u;
  memcpy(&u, &d, 8);
  return u == 0x7FF8000000000000ull;
}

